>
  <TabItem value="define-entity-class">

```ts
// owning side
const BookSchema = defineEntity({
  name: 'Book',
  properties: {
    id: p.integer().primary(),
    tags: () => p.manyToMany(BookTag).inversedBy('books'),
  },
});

export class Book extends BookSchema.class {}
BookSchema.setClass(Book);

// inverse side
const BookTagSchema = defineEntity({
  name: 'BookTag',
  properties: {
    id: p.integer().primary(),
    books: () => p.manyToMany(Book).mappedBy('tags'),
  },
});

export class BookTag extends BookTagSchema.class {}
BookTagSchema.setClass(BookTag);
```

  </TabItem>

<TabItem value="define-entity">

```ts
// owning side
export const Book = defineEntity({
  name: 'Book',
  properties: {
    id: p.integer().primary(),
    tags: () => p.manyToMany(BookTag).inversedBy('books'),
  },
});

// inverse side
export const BookTag = defineEntity({
  name: 'BookTag',
  properties: {
    id: p.integer().primary(),
    books: () => p.manyToMany(Book).mappedBy('tags'),
  },
});
```
